ns.data.spellAuraDescriptionOverrides[1289378] = { en = "The embers of Fiery Burst protect you from the effects of Biting Cold.", description = "Le braci dell'Esplosione Fiammeggiante ti proteggono dagli effetti del Freddo Mordente." }
