ns.data.spellAuraDescriptionOverrides[1218276] = { en = "The forces of the Scourge grow stronger. Chance to dodge reduced by ${$s1/$u}% and chance to be hit increased by ${$s2/$u}%.\r\n\r\nThe benefits from your Seal of the Dawn cannot exceed Rank ${$s3/$u}.", description = "Le forze del Flagello si rafforzano. Probabilità di schivata ridotta del ${$s1/$u}% e probabilità di essere colpiti aumentata del ${$s2/$u}%.\r\n\r\nI benefici del tuo Sigillo dell’Aurora non possono superare il Grado ${$s3/$u}." }
